--
-- Name: clear_price_floor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_price_floor(p_variant uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_business_id() IS NULL THEN RAISE EXCEPTION 'no tenant context'; END IF;
  DELETE FROM price_floors WHERE variant_id = p_variant AND business_id = current_business_id();
END $$;


--
-- Name: current_business_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_business_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT NULLIF(current_setting('app.business_id', true), '')::uuid
$$;


--
-- Name: enable_tenant_rls(regclass, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enable_tenant_rls(tbl regclass, col text DEFAULT 'business_id'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', tbl);
  EXECUTE format('CREATE POLICY tenant_isolation ON %s USING (%I = current_business_id()) WITH CHECK (%I = current_business_id())', tbl, col, col);
END $$;


--
-- Name: notify_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE conv uuid;
BEGIN
  IF TG_TABLE_NAME = 'conversations' THEN conv := NEW.id;
  ELSIF TG_TABLE_NAME IN ('messages','handoffs','deals') THEN conv := NEW.conversation_id;
  END IF;
  PERFORM pg_notify('salesai_changes', json_build_object('b', NEW.business_id, 't', TG_TABLE_NAME, 'c', conv)::text);
  RETURN NULL;
END $$;


--
-- Name: price_floor_is_set(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_floor_is_set(p_variant uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_business_id() IS NULL THEN RAISE EXCEPTION 'no tenant context'; END IF;
  RETURN EXISTS (SELECT 1 FROM price_floors WHERE variant_id = p_variant AND business_id = current_business_id());
END $$;


--
-- Name: set_price_floor(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_price_floor(p_variant uuid, p_floor numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_business_id() IS NULL THEN RAISE EXCEPTION 'no tenant context'; END IF;
  INSERT INTO price_floors (variant_id, business_id, floor_price)
  VALUES (p_variant, current_business_id(), p_floor)
  ON CONFLICT (variant_id) DO UPDATE SET floor_price = EXCLUDED.floor_price, updated_at = now();
END $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END $$;




